import{_ as d,C as n,o as s,c as e,j as i,E as r,a as l,a2 as o}from"./chunks/framework.C21TwvGF.js";const p=JSON.parse(`{"title":"5-hafta (Mentor)","description":"","frontmatter":{"title":"5-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"n":5,"bob":"III-bob · Mikrokontrollerlar va IoT qurilmalari (Arduino, ESP8266, ESP32)","lessons":[{"g":13,"title":"IoT uchun asosiy qurilmalar: Arduino va Raspberry Pi taqqosi","lead":"Biri — bitta ishni yillar davomida to'xtovsiz bajaradigan «tirishqoq ishchi», ikkinchisi — kaftga sig'adigan haqiqiy kompyuter. Bugun Arduino va Raspberry Pi'ni yonma-yon qo'yib, qaysi loyihaga qaysi biri kerakligini o'rganamiz.","link":"/mentor/9-sinf-iot/hafta-05/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-05/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-05/dars-1-test.html"},{"g":14,"title":"IoT uchun asosiy qurilmalar: ESP8266 va ESP32 imkoniyatlari","lead":"Tirnoqdek chip, ichida esa Wi-Fi, ba'zan Bluetooth ham. Aqlli rozetka, aqlli lampa va ko'plab «aqlli» uy jihozlari ichida aynan shunday modullar ishlaydi. Bugun ESP8266 va ESP32 bilan tanishamiz.","link":"/mentor/9-sinf-iot/hafta-05/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-05/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-05/dars-2-test.html"},{"g":15,"title":"Mikrokontroller tushunchasi va IoT qurilmalaridagi o'rni (1-qism)","lead":"Kir yuvish mashinasi, mikroto'lqinli pech, televizor pulti, avtomobil tormozi — ularning hammasi ichida kichik «kompyuter» yashirinib ishlaydi. Bu — mikrokontroller. Bugun uning ichida nima borligini va qanday ishlashini bilib olamiz.","link":"/mentor/9-sinf-iot/hafta-05/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-05/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-05/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-05/index.md","filePath":"mentor/9-sinf-iot/hafta-05/index.md"}`),h={name:"mentor/9-sinf-iot/hafta-05/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},g={class:"blk"},b={id:"baholash-mezoni",tabindex:"-1"};function v(k,a,q,c,y,P){const t=n("Icon");return s(),e("div",null,[i("div",u,[i("h2",m,[r(t,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan. Natijani hujjat (jadval, rasm) yoki Tinkercad/Wokwi havolasi va skrinshotlar bilan topshiring.</p><hr><h2 id="_13-dars-arduino-va-raspberry-pi" tabindex="-1">13-dars: Arduino va Raspberry Pi <a class="header-anchor" href="#_13-dars-arduino-va-raspberry-pi" aria-label="Permalink to &quot;13-dars: Arduino va Raspberry Pi&quot;">​</a></h2><ol><li>Arduino UNO va Raspberry Pi 4 ni 6 mezon bo&#39;yicha taqqoslovchi jadval tuzing: OS, protsessor/RAM, tarmoq, dasturlash tili, energiya, narx.</li><li>Har bir qurilma uchun 2 tadan real IoT loyiha misolini yozing va nega aynan shu qurilma tanlanganini 1 jumlada asoslang.</li><li>Raspberry Pi Pico nega «mikrokompyuter» emas, balki mikrokontroller ekanini 2–3 jumlada tushuntiring.</li></ol><hr><h2 id="_14-dars-esp8266-va-esp32-imkoniyatlari" tabindex="-1">14-dars: ESP8266 va ESP32 imkoniyatlari <a class="header-anchor" href="#_14-dars-esp8266-va-esp32-imkoniyatlari" aria-label="Permalink to &quot;14-dars: ESP8266 va ESP32 imkoniyatlari&quot;">​</a></h2><ol><li>ESP8266 va ESP32 taqqoslash jadvalini tuzing (7 xususiyat: tezlik, yadrolar, Wi-Fi, Bluetooth, GPIO, ADC, UART).</li><li>Wi-Fi&#39;ga ulanish dasturini (<code>WiFi.h</code>) qatorma-qator izohlang; Station va Access Point rejimlariga bittadan misol keltiring.</li><li>3 ta loyihaga mos modulni tanlang va asoslang: (a) Wi-Fi rele; (b) Bluetooth&#39;li qadam sanagich; (c) 5 ta sensorli ob-havo stansiyasi + ekran + bulut.</li><li>Qo&#39;shimcha: Wokwi&#39;da ESP32 Wi-Fi ulanish kodini ishga tushirib, IP va RSSI qiymatlarini skrinshot bilan yuboring.</li></ol><hr><h2 id="_15-dars-mikrokontroller-tushunchasi-1-qism" tabindex="-1">15-dars: Mikrokontroller tushunchasi (1-qism) <a class="header-anchor" href="#_15-dars-mikrokontroller-tushunchasi-1-qism" aria-label="Permalink to &quot;15-dars: Mikrokontroller tushunchasi (1-qism)&quot;">​</a></h2><ol><li>Mikrokontroller va mikroprotsessorni 5 mezon bo&#39;yicha taqqoslovchi jadval tuzing (tuzilishi, vazifasi, tezlik/quvvat, narx, misollar).</li><li>Arduino UNO rasmida ATmega328P, raqamli pinlar (14), analog pinlar (6), 5V/3.3V/GND, USB-B va kvars generatorni belgilang.</li><li>«Tugma → LED» dasturida Input va Output qatorlarini, RAM&#39;dagi o&#39;zgaruvchini va CPU qaror qabul qiladigan qatorni belgilang. Tok o&#39;chib-yonsa nima saqlanishini yozing.</li><li>Uyingizdan ichida mikrokontroller ishlaydigan 5 ta qurilmani toping va har birining «bitta vazifasini» yozing.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>13-dars vazifasi (30 ball):</strong> jadval 6 mezonli va to&#39;g&#39;ri (Arduino — OS yo&#39;q, modul kerak; Pi — Linux, Wi-Fi/BT/Ethernet), loyiha misollari mantiqiy asoslangan, Pico — RP2040 mikrokontroller ekani tushuntirilgan.</li><li><strong>14-dars vazifasi (35 ball):</strong> jadvaldagi qiymatlar (80 va 160–240 MHz, 1 va 2 yadro, BT faqat ESP32, ~17 va ~34+ GPIO), kod izohi (<code>WiFi.begin</code>, <code>WL_CONNECTED</code>, <code>localIP</code>, <code>RSSI</code>), Station/AP misollari, tanlov: (a) ESP8266, (b) ESP32, (c) ESP32.</li><li><strong>15-dars vazifasi (35 ball):</strong> MCU/MPU jadvali to&#39;liq, plata xaritasi 6 qismni to&#39;g&#39;ri ko&#39;rsatadi, kod qismlari to&#39;g&#39;ri belgilangan (Flash saqlanadi, RAM yo&#39;qoladi), 5 ta qurilma va vazifalari.</li></ul><p>Dasturdagi shkala: <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>15-dars — mavzuning 1-qismi. Sensor → MCU → aktuator → bulut zanjiri va analog/raqamli pinlar 16-darsda chuqurlashtiriladi, shuning uchun bu haftada faqat tuzilish va qismlar baholanadi.</li></ul>',17))]),i("div",g,[i("h2",b,[r(t,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>IoT uchun asosiy qurilmalar: Arduino va Raspberry Pi — mikrokontroller va mikrokompyuter, tuzilishi, OS, dasturlash, modellar, tanlash mezonlari</li><li>ESP8266 va ESP32 imkoniyatlari: ichki Wi-Fi, Bluetooth, ikki yadro, Station/AP, HTTP/MQTT/WebSocket, interfeyslar, Deep Sleep, <code>WiFi.h</code> bilan ulanish</li><li>Mikrokontroller tushunchasi va IoT qurilmalaridagi o&#39;rni (1-qism): MCU va MPU, kompyuterdan farqi, CPU, Flash/RAM/EEPROM, Input/Output portlar, Arduino UNO tuzilishi</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Arduino va Raspberry Pi</strong></td><td>Mikrokontroller va mikrokompyuter farqi, Arduino UNO va Pi tuzilishi, OS va tillar, 6 mezonli taqqoslash, loyihaga qurilma tanlash va asoslash</td><td>30 ball</td></tr><tr><td><strong>ESP8266 va ESP32</strong></td><td>Xususiyatlar jadvali, Station va AP rejimlari, protokollar, Arduino IDE&#39;ga plata qo&#39;shish, Wi-Fi ulanish kodini izohlash, IP va RSSI tahlili, modul tanlash</td><td>35 ball</td></tr><tr><td><strong>Mikrokontroller tuzilishi (1-qism)</strong></td><td>MCU ta&#39;rifi, MCU/MPU jadvali va o&#39;xshatish, CPU, Flash/RAM/EEPROM farqi, Input/Output rejimlari, Arduino UNO plata xaritasi, «tugma → LED» tahlili</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><p>Dasturdagi shkala: <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Arduino va Pi (30)</th><th>ESP8266/ESP32 (35)</th><th>MCU tuzilishi (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> o&#39;quvchilar Raspberry Pi Pico va ESP32 ni ko&#39;pincha «mikrokompyuter» deb ataydi — OS bor-yo&#39;qligini asosiy mezon sifatida qayta-qayta so&#39;rang. ESP darsida eng ko&#39;p uchraydigan amaliy xato — Board noto&#39;g&#39;ri tanlangani va Serial Monitor tezligi mos emasligi.</li><li><strong>Tekshirish usuli:</strong> har bir o&#39;quvchidan «tugma → LED» dasturida ma&#39;lumot yo&#39;lini og&#39;zaki aytib berishni so&#39;rang: port xabar oladi → CPU Flash&#39;dagi dastur bo&#39;yicha tahlil qiladi → port javob beradi; tok o&#39;chsa Flash va RAM&#39;da nima bo&#39;lishini so&#39;rang.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> ESP32&#39;da Access Point rejimida oddiy web-sahifa orqali LED boshqarish, Deep Sleep bilan batareya muddatini hisoblash, EEPROM&#39;da tugma bosilishlar sonini saqlash.</li></ul>',12))])])}const z=d(h,[["render",v]]);export{p as __pageData,z as default};
